#include <stdio.h>
#include <string.h>
#include "laststate/latch.h"
#define CHECK(x) do{if(!(x)){fprintf(stderr,"power-loss check failed: %s:%d\n",#x,__LINE__);return 1;}}while(0)
static uint8_t bytes[50000];static unsigned sent;static bool yes(void *x){(void)x;return true;}static size_t mtu(void *x){(void)x;return LS_MAX_EVENT_SIZE;}static ls_result_t send_data(void *x,const uint8_t *data,size_t length){(void)x;if(ls_envelope_validate(data,length,0)!=LS_OK)return LS_ECORRUPT;sent++;return LS_OK;}
static int boot_runtime(ls_storage_backend_t *storage,ls_transport_backend_t *transport){static ls_identity_t identity={.project_id="power",.device_id="one",.firmware_build_id="power001"};ls_config_t config={.identity=&identity};CHECK(ls_init(&config)==LS_OK);ls_storage_register(storage);ls_transport_register(transport);CHECK(ls_boot()==LS_OK);return 0;}
int main(void){for(uint32_t failure=1;failure<=18;failure++){memset(bytes,0xff,sizeof bytes);ls_storage_sim_t simulator={bytes,sizeof bytes,false,0,0,0};ls_storage_backend_t storage={"sim",&simulator,sizeof bytes,1,1,ls_storage_sim_read,ls_storage_sim_write,ls_storage_sim_erase,ls_storage_sim_sync};ls_transport_backend_t transport={.name="sink",.priority=1,.available=yes,.send=send_data,.max_payload=mtu};CHECK(boot_runtime(&storage,&transport)==0);ls_storage_sim_fail_at(&simulator,failure,7);ls_capture_message("power cut",LS_SEVERITY_ERROR);ls_storage_sim_reset_faults(&simulator);CHECK(boot_runtime(&storage,&transport)==0);sent=0;ls_result_t flush=ls_flush();CHECK(flush==LS_OK||flush==LS_EAGAIN);CHECK(sent<=1);}return 0;}
